package backend

import "context"

const PreviewExecutionProtocol = 1

// ReviewedSourcePreview serves the bounded generic static profile. It does not
// build or import an application image.
const ReviewedSourcePreview = "reviewed-source"

// PreviewIdentity is generated by Luci, never supplied as a Docker target by a
// browser. Build and serving allocations share the reviewed release/source but
// have separate allocation IDs, phases and capacity reservations.
type PreviewIdentity struct {
	Kind              string `json:"kind,omitempty"`
	SnapshotDigest    string `json:"snapshotDigest,omitempty"`
	CommandDigest     string `json:"commandDigest,omitempty"`
	EnvironmentDigest string `json:"environmentDigest,omitempty"`
	RuntimeImageID    string `json:"runtimeImageId,omitempty"`
	Protocol          int    `json:"protocol"`
	EngineID          string `json:"engineId"`
	InstanceID        string `json:"instanceId"`
	AllocationID      string `json:"allocationId"`
	ReleaseID         string `json:"releaseId"`
	ScopeDigest       string `json:"scopeDigest"`
	ProjectID         string `json:"projectId"`
	SourceDigest      string `json:"sourceDigest"`
	Commit            string `json:"commit"`
}

type PreviewSpec struct {
	Identity        PreviewIdentity
	Kind            string
	Resources       Resources
	SourceDirectory string
	SourceArchive   []byte
	ContextDigest   string
	Dockerfile      string
	Port            int
	Environment     map[string]string
	Network         string
	Labels          map[string]string
	ImageID         string
}

type PreparedPreview struct {
	Spec              PreviewSpec
	StorageDriver     string
	RequiredDiskBytes uint64
	// PreparedContext is a bounded tar; warm FROM images are pinned and cold
	// declarations are bound by BasePlan. Build pins every image before dispatch.
	// The tar is ephemeral, never in the durable lease or browser-facing outcome.
	PreparedContext []byte
	ContextDigest   string
	BaseImages      []string
	// BasePlan is derived only from the reviewed Dockerfile. A missing ImageID
	// means Prepare observed confirmed absence, never an unavailable engine.
	BasePlan       []PreviewBaseImage
	BasePlanDigest string
	// SourcePayload is ephemeral static content, never persisted in leases or
	// returned to the browser. Its fixed server only reads these bytes in memory.
	SourcePayload     []byte
	SourceEnvironment []string
}

type PreviewBaseImage struct {
	Reference string
	ImageID   string
	// Observed virtual size when warm; the supported policy cap when cold.
	VirtualSizeBytes uint64
}

type PreviewBuildResult struct {
	ImageID               string
	ImageVirtualSizeBytes uint64
	Settled               bool
}

type PreviewObservation struct{ Ref, State, URL string }

// No method retries a mutating RPC. The coordinator persists intent before
// each call and retains capacity for unknown build/Create outcomes. Settled
// requires a complete backend reply, never merely client cancellation.
type PreviewExecutor interface {
	PreparePreview(context.Context, PreviewSpec) (PreparedPreview, error)
	// beforeMutation rechecks the exact active lease, current Deploy authority
	// and reviewed source before every declared-base pull and final image build.
	// It is mandatory; pulls share this build allocation and are never replayed.
	BuildPreview(context.Context, PreparedPreview, func(context.Context) error) (PreviewBuildResult, error)
	CreatePreview(context.Context, PreparedPreview) (string, error)
	StartPreview(context.Context, PreviewIdentity, string) error
	StopPreview(context.Context, PreviewIdentity, string) error
	InspectPreview(context.Context, PreviewIdentity, string) (PreviewObservation, error)
	RemovePreview(context.Context, PreviewIdentity, string) error
}
